import type { Example } from "../example.ts"
import { html, type TemplateResult } from "lit-html"

export type PresenceTone = "green" | "amber" | "red" | "neutral"
export type PresenceSize = "xs" | "sm" | "md" | "lg" | "xl"

export type PresenceDotProps = { tone: PresenceTone; label: string; size?: PresenceSize; class?: string }

const base = "inline-block rounded-full"

const tones: Record<PresenceTone, string> = {
  green: "bg-trust-green",
  amber: "bg-trust-amber",
  red: "bg-trust-red",
  neutral: "border border-muted bg-surface",
}

// daisyUI sizes in 4px steps (2, 4, 8, 12, 16); lg is the 12px dot token and the default, the spacing scale stands in for the rest.
const sizes: Record<PresenceSize, string> = {
  xs: "w-0.5 h-0.5",
  sm: "w-1 h-1",
  md: "w-2 h-2",
  lg: "w-dot h-dot",
  xl: "w-4 h-4",
}

/** Apps put these classes on their own dot. Without a tone the dot has no fill: the app sets its colour as the background. */
export function presenceDotClass(tone?: PresenceTone, size: PresenceSize = "lg"): string {
  return tone === undefined ? `${base} ${sizes[size]}` : `${base} ${tones[tone]} ${sizes[size]}`
}

// The colour is never the only cue: the label is the image's name.
export function presenceDot(props: PresenceDotProps): TemplateResult {
  const classes = [presenceDotClass(props.tone, props.size)]
  if (props.class !== undefined) classes.push(props.class)
  return html`<span role="img" aria-label=${props.label} class=${classes.join(" ")}></span>`
}

export const examples: Example[] = [
  { label: "green", render: () => presenceDot({ tone: "green", label: "Online" }) },
  { label: "amber", render: () => presenceDot({ tone: "amber", label: "Away" }) },
  { label: "red", render: () => presenceDot({ tone: "red", label: "Offline" }) },
  { label: "neutral", render: () => presenceDot({ tone: "neutral", label: "Unknown" }) },
  { label: "xs", render: () => presenceDot({ tone: "green", label: "Online", size: "xs" }) },
  { label: "sm", render: () => presenceDot({ tone: "green", label: "Online", size: "sm" }) },
  { label: "md", render: () => presenceDot({ tone: "green", label: "Online", size: "md" }) },
  { label: "lg", render: () => presenceDot({ tone: "green", label: "Online", size: "lg" }) },
  { label: "xl", render: () => presenceDot({ tone: "green", label: "Online", size: "xl" }) },
]
